Method.Source:
    /// <summary>
    /// Performs item substitution.
    /// </summary>
    /// <param name = "_salesOrderLineEntity">SalesOrderLineEntity</param>
    /// <param name = "_inventDim">Inventory dimension</param>
    /// <param name = "_orderedQty">Ordered quantity</param>
    /// <param name = "_outOfStockOnly">Search for Out of Stock substition type only</param>
    /// <param name = "_searchParent">Search parent</param>
    /// <returns>True if the item substitution is successful</returns>
    public boolean substituteItem(SalesOrderLineV2Entity    _salesOrderLineEntity,
                                  InventDim                 _inventDim,
                                  InventQty                 _orderedQty,
                                  boolean                   _outOfStockOnly = false,
                                  boolean                   _searchParent = true)
    {
        SalesTable                      salesTable;
        METSalesLine                    metSalesLine;        
        boolean                         modified;

        salesTable  = SalesTable::find(_salesOrderLineEntity.SalesOrderNumber);        

        if (salesTable.metSubstitutionActive())
        {
            METSalesItemSubstitution metSalesItemSubstitution = METSalesItemSubstitution::construct();

            boolean found   = metSalesItemSubstitution.findSubstitutionItem(_salesOrderLineEntity.ItemNumber,
                                                                            _inventDim,
                                                                            salesTable.CustAccount,
                                                                            salesTable.custTable_CustAccount().CustGroup,
                                                                            _orderedQty,
                                                                            _outOfStockOnly,
                                                                            _searchParent);
            metSalesLine    = metSalesItemSubstitution.parmMetSalesLine();

            if (found && 
                metSalesLine.SubstituteReplacementItemID != '' &&
                _salesOrderLineEntity.ItemNumber != metSalesLine.SubstituteReplacementItemID)
            {
                UnitOfMeasureSymbol salesUnit   = metSalesItemSubstitution.substitutionItemSalesUnit(metSalesLine.SubstituteReplacementItemID, salesTable.InventSiteId);
                SalesQty    salesQty            = metSalesItemSubstitution.substitutionItemSalesQty(_salesOrderLineEntity.ItemNumber,
                                                                                                metSalesLine.SubstituteReplacementItemID,
                                                                                                salesTable.InventSiteId,
                                                                                                salesUnit,
                                                                                                _orderedQty,
                                                                                                metSalesItemSubstitution.parmRounding());

                _salesOrderLineEntity.ItemNumber                        = metSalesLine.SubstituteReplacementItemID;
                _salesOrderLineEntity.OrderedSalesQuantity              = salesQty;
                _salesOrderLineEntity.SalesUnitSymbol                   = salesUnit;

                _salesOrderLineEntity.METSubstituteOriginalItemID       = metSalesLine.SubstituteOriginalItemID;
                _salesOrderLineEntity.METSubstituteReplacementItemID    = metSalesLine.SubstituteReplacementItemID;
                _salesOrderLineEntity.METSubstituteParentItemID         = metSalesLine.SubstituteParentItemID;
                _salesOrderLineEntity.METSubstitutionType               = metSalesLine.SubstitutionType;
                _salesOrderLineEntity.METSubstitutionCode               = metSalesLine.SubstitutionCode;
                _salesOrderLineEntity.METSubstitutionSetupRefRecID      = metSalesLine.SubstitutionSetupRefRecID;
                
                modified    = true;
            }
        }

        return modified;
    }

    /// <summary>
    /// Performs pallet rounding.
    /// </summary>
    /// <param name = "_salesOrderLineEntity">SalesOrderLineEntity</param>
    /// <param name = "_inventDim">Inventory dimension</param>
    /// <param name = "_inventUnit">Inventory unit</param>
    /// <param name = "_orderedQty">Ordered quantity</param>
    /// <returns>True if the pallet rounding is successful</returns>
    public boolean  applyPalletRounding(SalesOrderLineV2Entity      _salesOrderLineEntity,
                                        InventDim                   _inventDim,
                                        UnitOfMeasureSymbol         _inventUnit,
                                        InventQty                   _orderedQty)
    {
        SalesQty            originalSalesQty    = _salesOrderLineEntity.OrderedSalesQuantity;
        SalesTable          salesTable          = SalesTable::find(_salesOrderLineEntity.SalesOrderNumber);
        InventQty           newOrderedQty;
        boolean             modified;

        METPalletRounding   metPalletRounding;
 
        if (salesTable.agreementIsLinked())
        {
            return false;
        }
             
        metPalletRounding   = new METPalletRounding();

        newOrderedQty   = metPalletRounding.applyPalletRounding(_salesOrderLineEntity.ItemNumber,
                                                                salesTable.CustAccount,
                                                                _salesOrderLineEntity.ShippingSiteId,
                                                                _orderedQty);

        if ((newOrderedQty > _orderedQty) &&
            METCustParameters::Find().PalletRoundingCheckStock)
        {
            if (newOrderedQty > this.onHandInventory(_salesOrderLineEntity.ItemNumber, _inventDim))
            {
                newOrderedQty   = _orderedQty;
            }
        }

        if (newOrderedQty > _orderedQty)
        {
            if (_inventUnit  == _salesOrderLineEntity.SalesUnitSymbol)
            {
                _salesOrderLineEntity.OrderedSalesQuantity   = newOrderedQty;
            }
            else
            {
                SalesQty    newSalesQty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_salesOrderLineEntity.ItemNumber,
                                                                                                  _inventDim.inventDimId,
                                                                                                  newOrderedQty,
                                                                                                  _inventUnit,
                                                                                                  _salesOrderLineEntity.SalesUnitSymbol,
                                                                                                  NoYes::Yes);
                newSalesQty  = decRound(newSalesQty, InventTable::inventDecimals(_salesOrderLineEntity.ItemNumber));

                _salesOrderLineEntity.OrderedSalesQuantity   = newSalesQty;
            }

            _salesOrderLineEntity.METPalletRoundingApplied       = NoYes::Yes;
            _salesOrderLineEntity.METPalletRoundingOriginalQty   = originalSalesQty;
            
            modified = true;            
        }

        return modified;
    }

    /// <summary>
    /// Finds the onhand inventory of a given item.
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_inventDim">Inventory dimension</param>
    /// <returns>The onhand inventory of a given item</returns>
    public InventQtyAvailPhysical onHandInventory(ItemId _itemId, InventDim _inventDim)
    {
        InventDimParm   onHandDimParm;
        onHandDimParm.initFromInventDim(_inventDim);

        InventOnhand    onHand = InventOnhand::newItemDim(_itemId, _inventDim, onHandDimParm);
                        
        return onHand.availPhysical();
    }

    /// <summary>
    /// Calculates inventory quantity from sales quantity.
    /// </summary>
    /// <param name = "_salesorderLineEntity">SalesorderLineEntity</param>
    /// <param name = "_inventDimId">Inventory dimension Id</param>
    /// <param name = "_inventUnit">Inventory unit</param>
    /// <returns>Inventory quantity</returns>
    public InventQty calculateInventoryQty(SalesOrderLineV2Entity   _salesorderLineEntity, 
                                           InventDimId              _inventDimId, 
                                           UnitOfMeasureSymbol      _inventUnit)
    {
        InventQty   orderedQty;

        if (_inventUnit  == _salesorderLineEntity.SalesUnitSymbol)
        {
            orderedQty  = _salesorderLineEntity.OrderedSalesQuantity;
        }
        else
        {
            orderedQty  = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_salesorderLineEntity.ItemNumber,
                                                                                                  _inventDimId,
                                                                                                  _salesorderLineEntity.OrderedSalesQuantity,
                                                                                                  _salesorderLineEntity.SalesUnitSymbol,
                                                                                                  _inventUnit,
                                                                                                  NoYes::Yes);
            orderedQty  = decRound(orderedQty, InventTable::inventDecimals(_salesorderLineEntity.ItemNumber));
        }

        return orderedQty;
    }

    /// <summary>
    /// Check order guides.
    /// </summary>
    /// <param name = "_salesOrderLineEntity">_salesOrderLineEntity</param>
    /// <param name = "_custAccount">_custAccount</param>
    /// <returns>True if the order guide check failed</returns>
    public boolean checkOrderGuides(SalesOrderLineV2Entity      _salesOrderLineEntity,
                                    CustAccount                 _custAccount)
    {
        boolean ret = true;

        if(!METSalesOrderGuideExecution::isItemOrderable(_custAccount, _salesOrderLineEntity.ItemNumber))
        {
            _salesOrderLineEntity.METReasonId   = METCustParameters::Find().OrderGuideNotInRangeReasonId;
            ret = false;
        }

        return ret;
    }
